/* Real-simulator observations: self-reported data, never an iRating predictor. */
(function(root){
  'use strict';
  const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const median=a=>{const s=a.slice().sort((x,y)=>x-y);return s.length?(s[Math.floor((s.length-1)/2)]+s[Math.ceil((s.length-1)/2)])/2:null;};
  function parseLaps(text){
    const rows=String(text).split(/\r?\n/).map(s=>s.trim()).filter(Boolean),laps=[],errors=[];
    if(rows.length>200)return{laps:[],errors:['한 세션은 최대 200랩입니다.']};
    rows.forEach((line,i)=>{const valid=!line.startsWith('!'),value=valid?line:line.slice(1).trim(),match=value.match(/^(?:(\d{1,2}):)?(\d{1,4}(?:\.\d{1,3})?)$/);if(!match){errors.push((i+1)+'행: 1:45.321 또는 105.321 형식으로 입력하세요.');return;}const seconds=Number(match[2]),time=(match[1]?Number(match[1])*60:0)+seconds;if(time<=0||time>3600||(match[1]&&seconds>=60)){errors.push((i+1)+'행: 유효한 랩타임이 아닙니다.');return;}laps.push({time,valid});});
    return{laps,errors};
  }
  function stats(laps){
    const times=laps.filter(l=>l.valid).map(l=>l.time),n=times.length,mean=n?times.reduce((a,b)=>a+b,0)/n:null;
    return{total:laps.length,valid:n,validRate:laps.length?n/laps.length:0,best:n?Math.min(...times):null,median:median(times),range:n>1?Math.max(...times)-Math.min(...times):null,sd:n>1?Math.sqrt(times.reduce((sum,x)=>sum+(x-mean)**2,0)/n):null,fade:n>=6?median(times.slice(Math.ceil(n/2)))-median(times.slice(0,Math.floor(n/2))):null};
  }
  function lapTime(v){if(!Number.isFinite(v))return'—';return Math.floor(v/60)+':'+(v%60).toFixed(3).padStart(6,'0');}
  const key='intsRealSessionsV1',noteKey='intsCornerNotesV1';
  const games=['LMU','ACC','AMS2','EA WRC','AC','ACR','iRacing','F1','기타'];
  const tracks=['monza','nurbgp','rally_stage','playground','touge','custom'];
  const vehicles=['gt3','hypercar','formula','rally1','ae86','touring_fwd','midship','rearengine'];
  function validSession(s){return s&&typeof s.id==='string'&&s.id.length<80&&typeof s.at==='string'&&Number.isFinite(Date.parse(s.at))&&games.includes(s.game)&&['car','track','conditions','focus','review'].every(k=>typeof s[k]==='string'&&s[k].length<=2000)&&Number.isInteger(s.incidents)&&s.incidents>=0&&s.incidents<=999&&Array.isArray(s.laps)&&s.laps.length>0&&s.laps.length<=200&&s.laps.every(l=>l&&Number.isFinite(l.time)&&l.time>0&&l.time<=3600&&typeof l.valid==='boolean');}
  function validNote(n){return n&&typeof n.id==='string'&&n.id.length<80&&tracks.includes(n.trackId)&&vehicles.includes(n.vehicle)&&games.includes(n.game)&&['trackName','car','corner','reference','gear','conditions','warning'].every(k=>typeof n[k]==='string'&&n[k].length<=2000)&&['hypothesis','tested'].includes(n.status)&&typeof n.at==='string'&&Number.isFinite(Date.parse(n.at));}
  function mount(element,{onLaunch=()=>{}}={}){
    let sessions=[],notes=[],saveBlocked=false,mode='stints',selected=null;
    try{const a=JSON.parse(localStorage.getItem(key)||'[]'),b=JSON.parse(localStorage.getItem(noteKey)||'[]');sessions=Array.isArray(a)?a.filter(validSession).slice(-100):[];notes=Array.isArray(b)?b.filter(validNote).slice(-200):[];}catch(_){saveBlocked=true;}
    if(!document.getElementById('transfer-css')){const style=document.createElement('style');style.id='transfer-css';style.textContent=`
      .tr-top{display:flex;gap:10px;margin-bottom:20px;flex-wrap:wrap}.tr-top .active{color:#172315;background:var(--lime);border-color:var(--lime)}.tr-layout{display:grid;grid-template-columns:minmax(300px,.95fr) minmax(0,1.4fr);gap:20px}.tr-form,.tr-list{padding:22px}.tr-form h2,.tr-list h2{font-size:19px;margin-bottom:12px}.tr-form>p,.tr-list>p{font-size:12px;color:var(--muted);margin-bottom:18px}.tr-fields{display:grid;grid-template-columns:1fr 1fr;gap:12px}.tr-field{display:flex;flex-direction:column;gap:5px}.tr-field.wide{grid-column:1/-1}.tr-field input,.tr-field textarea,.tr-field select{width:100%;background:#0b141c;color:var(--text);border:1px solid #334650;border-radius:5px;padding:9px 11px;font-size:12px}.tr-field textarea{resize:vertical;min-height:80px;line-height:1.8}.tr-field label{font-size:11px}.tr-actions{display:flex;align-items:center;gap:10px;margin-top:17px;flex-wrap:wrap}.tr-error{font-size:12px;color:var(--coral);margin-top:12px;white-space:pre-line}.tr-success{font-size:12px;color:var(--lime);margin-top:12px}.tr-preview{font-size:11px;color:var(--cyan);margin-top:10px;line-height:1.8}.tr-item{border:1px solid var(--line);background:#0c161e;padding:16px;border-radius:6px;margin-bottom:12px}.tr-item h3{font-size:14px;margin-bottom:7px}.tr-item p{font-size:11px;color:var(--muted);margin:7px 0;line-height:1.8}.tr-item .tr-metrics{display:flex;gap:14px;flex-wrap:wrap;font:12px var(--mono);color:var(--lime)}.tr-meta{font-size:10px;color:#8ba0ae}.tr-empty{padding:32px 16px;text-align:center;color:var(--muted);font-size:12px;border:1px dashed var(--line);border-radius:6px}.tr-detail{grid-column:1/-1;padding:22px}.tr-notice{padding:16px 20px;border:1px solid #3a4c5a;background:#13212b;border-radius:7px;font-size:12px;line-height:1.8;color:#b8c9d5;margin-bottom:20px}.tr-notice strong{color:var(--text)}.tr-source-table{width:100%;font-size:11px}.tr-source-table td{font-family:inherit}.tr-schema{font:11px var(--mono);white-space:pre-wrap;overflow-wrap:anywhere;padding:13px;background:#0a131a;border-radius:5px}.tr-section-title{font-size:15px;margin:16px 0 9px}.tr-svg{width:100%;height:100px;display:block;margin:12px 0}.tr-storage{font-size:10px;color:var(--muted);margin-top:14px}@media(max-width:950px){.tr-layout{grid-template-columns:1fr}.tr-form,.tr-list{padding:18px}}@media(max-width:480px){.tr-fields{grid-template-columns:1fr}.tr-field.wide{grid-column:auto}.tr-top .btn{font-size:10px;padding:9px 11px}}`;
      document.head.appendChild(style);
    }
    const q=s=>element.querySelector(s);
    function persist(){try{localStorage.setItem(key,JSON.stringify(sessions));localStorage.setItem(noteKey,JSON.stringify(notes));saveBlocked=false;}catch(_){saveBlocked=true;}}
    function formSelect(id,label,items){return'<div class="tr-field"><label for="'+id+'">'+label+'</label><select id="'+id+'">'+items.map(x=>'<option value="'+esc(typeof x==='string'?x:x.value)+'">'+esc(typeof x==='string'?x:x.label)+'</option>').join('')+'</select></div>';}
    function field(id,label,placeholder='',wide=false,type='text'){return'<div class="tr-field '+(wide?'wide':'')+'"><label for="'+id+'">'+label+'</label><input id="'+id+'" type="'+type+'" maxlength="'+(wide?2000:160)+'" placeholder="'+esc(placeholder)+'"'+(type==='number'?' min="0" max="999" value="0"':'')+'></div>';}
    function area(id,label,placeholder){return'<div class="tr-field wide"><label for="'+id+'">'+label+'</label><textarea id="'+id+'" maxlength="6000" placeholder="'+esc(placeholder)+'"></textarea></div>';}
    const trackOptions=()=>tracks.map(id=>({value:id,label:root.GripTracks?.catalog?.find?.(t=>t.id===id)?.name||({monza:'Monza',nurbgp:'Nürburgring GP',rally_stage:'가상 랠리 스테이지',playground:'플레이그라운드',touge:'가상 토우게',custom:'직접 지정'})[id]}));
    const vehicleOptions=()=>vehicles.map(id=>({value:id,label:root.GripPhysics?.vehicles?.[id]?.label||id}));
    function render(){
      element.innerHTML='<div class="tr-top"><button class="btn '+(mode==='stints'?'active':'')+'" data-tr="stints">실제 게임의 스틴트 기록</button><button class="btn '+(mode==='notes'?'active':'')+'" data-tr="notes">차량별 서킷 가이드 노트</button><button class="btn" data-tr="export">내 기록 내보내기 · JSON</button></div>'+(mode==='stints'?stintsView():notesView())+'<p class="tr-storage">직접 입력한 기록이며 게임과 자동 연결하지 않습니다. 이 브라우저에만 저장합니다. '+(saveBlocked?'브라우저 저장이 차단되어 현재 탭에서만 유지됩니다. 내보내기로 보관하세요.':'브라우저 데이터가 지워지기 전에 내보내기로 보관하세요.')+'</p>';
      if(mode==='stints'){q('#tr-laps').addEventListener('input',previewLaps);q('#tr-save-session').addEventListener('click',saveSession);}else{q('#tr-note-track').addEventListener('change',updateCornerChoices);q('#tr-save-note').addEventListener('click',saveNote);updateCornerChoices();}
    }
    function stintsView(){return'<div class="tr-notice"><strong>랩타임만으로 레이스 실력을 판정하지 않습니다.</strong><br>차량·트랙·연료·타이어·날씨를 맞춘 기록끼리 비교하세요. 중앙값·유효 랩 비율·편차를 먼저 보고, 실제 레이스에서 트래픽 대응을 따로 확인합니다. 아래 기록으로 iRating 2k~3k 달성 가능성을 계산하지 않습니다.</div><div class="tr-layout"><section class="card tr-form"><h2>오늘 확인한 질문 하나</h2><p>연습 뒤 실제 게임의 랩타임을 붙여 넣고, 다음에 바꿀 입력 하나를 적습니다.</p><div class="tr-fields">'+formSelect('tr-game','게임',games)+field('tr-car','실제 차량 이름','예: BMW M4 GT3')+field('tr-track','트랙·레이아웃','예: Monza GP')+field('tr-incidents','접촉·스핀·이탈 횟수 · 직접 기록','',false,'number')+field('tr-conditions','조건 · 연료 / 타이어 / 노면 / 셋업','예: 40 L / 신품 / 드라이 / 고정 셋업',true)+field('tr-focus','이번에 시험한 것','예: T1 브레이크 해제를 조금 부드럽게',true)+area('tr-laps','랩타임 · 한 줄에 한 랩 / 무효 랩은 ! 표시','1:49.321\n1:49.550\n!1:52.100')+area('tr-review','관찰한 결과와 다음 실험','빠르거나 느렸던 구간, 원인 후보 하나, 다음에 바꿀 입력 하나')+'</div><div id="tr-preview" class="tr-preview" aria-live="polite"></div><div id="tr-error" class="tr-error" role="alert"></div><div class="tr-actions"><button class="btn primary" id="tr-save-session">스틴트 저장</button><span class="fineprint">최대 100세션 · 200랩/세션</span></div></section><section class="card tr-list"><h2>실제 심의 연습 기록</h2><p>평균보다 중앙값을 먼저 보고, 유효 기록의 표준편차와 전체 시도의 성공률을 함께 봅니다.</p>'+sessionCards()+'</section></div>'+(selected?detail(selected):'');}
    function sessionCards(){if(!sessions.length)return'<div class="tr-empty">아직 입력한 실제 게임 기록이 없습니다.<br>연습 스틴트 5랩부터 기록해 보세요.</div>';return sessions.slice().reverse().map(s=>{const m=stats(s.laps);return'<article class="tr-item"><div class="tr-meta">'+esc(new Date(s.at).toLocaleString('ko-KR'))+' · '+esc(s.game)+'</div><h3>'+esc(s.car)+' / '+esc(s.track)+'</h3><div class="tr-metrics"><span>중앙값 '+lapTime(m.median)+'</span><span>유효 '+m.valid+'/'+m.total+'</span><span>편차 '+(m.sd===null?'—':m.sd.toFixed(3)+' s')+'</span></div><p>'+esc(s.focus)+'</p><p>'+esc(s.conditions)+'</p><button class="btn subtle" data-tr="detail" data-id="'+esc(s.id)+'">구간 분석 메모와 랩 보기</button></article>';}).join('');}
    function detail(id){const s=sessions.find(s=>s.id===id);if(!s)return'';const m=stats(s.laps),previous=sessions.filter(p=>p.id!==s.id&&p.at<s.at&&['game','car','track','conditions'].every(k=>p[k].trim().toLowerCase()===s[k].trim().toLowerCase())&&stats(p.laps).valid).sort((a,b)=>b.at.localeCompare(a.at))[0],diff=previous&&m.median!==null?m.median-stats(previous.laps).median:null;return'<section class="card tr-detail"><div class="section-heading"><h2>'+esc(s.game)+' · '+esc(s.track)+' · 직접 입력한 기록</h2><button class="btn subtle" data-tr="close">접기</button></div><div class="stat-grid"><div class="stat"><span>최속 유효 랩</span><strong>'+lapTime(m.best)+'</strong></div><div class="stat"><span>중앙값</span><strong>'+lapTime(m.median)+'</strong></div><div class="stat"><span>유효 랩 비율</span><strong>'+Math.round(m.validRate*100)+'<small>%</small></strong></div><div class="stat"><span>유효 랩 범위</span><strong>'+(m.range===null?'—':m.range.toFixed(3))+'<small>s</small></strong></div></div><p class="fineprint">동일한 게임·차량·트랙·조건 이름의 직전 세션 대비 중앙값: '+(diff===null?'비교 기록 없음':(diff>=0?'+':'')+diff.toFixed(3)+' s')+'. 후반−전반 중앙값: '+(m.fade===null?'유효 랩 6개부터 표시':(m.fade>=0?'+':'')+m.fade.toFixed(3)+' s')+'. 시간 변화만으로 타이어 열화나 원인을 확정하지 않습니다.</p><h3 class="tr-section-title">이번 질문</h3><p>'+esc(s.focus)+'</p><h3 class="tr-section-title">관찰 / 다음 실험</h3><p>'+esc(s.review).replace(/\n/g,'<br>')+'</p><div class="table-scroll"><table><thead><tr><th>랩</th><th>시간</th><th>상태</th></tr></thead><tbody>'+s.laps.map((l,i)=>'<tr><td>'+(i+1)+'</td><td>'+lapTime(l.time)+'</td><td class="'+(l.valid?'good':'bad')+'">'+(l.valid?'유효':'무효 · 계산 제외')+'</td></tr>').join('')+'</tbody></table></div></section>';}
    function previewLaps(){const p=parseLaps(q('#tr-laps').value);q('#tr-error').textContent=p.errors.join('\n');const m=stats(p.laps);q('#tr-preview').textContent=p.laps.length?'입력 '+m.total+'랩 · 유효 '+m.valid+'랩 · 중앙값 '+lapTime(m.median)+' · 편차 '+(m.sd===null?'—':m.sd.toFixed(3)+' s'):'';}
    function saveSession(){const p=parseLaps(q('#tr-laps').value),car=q('#tr-car').value.trim(),track=q('#tr-track').value.trim(),conditions=q('#tr-conditions').value.trim(),focus=q('#tr-focus').value.trim(),incidents=Number(q('#tr-incidents').value);const errors=p.errors.slice();if(!p.laps.length)errors.push('실제 랩타임을 1개 이상 입력하세요.');if(!car||!track||!conditions||!focus)errors.push('차량·트랙·조건·이번 질문을 모두 적어 주세요.');if(!Number.isInteger(incidents)||incidents<0||incidents>999)errors.push('실수 횟수는 0–999 정수로 입력하세요.');if(errors.length){q('#tr-error').textContent=errors.join('\n');return;}const s={id:Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,6),at:new Date().toISOString(),game:q('#tr-game').value,car,track,conditions,focus,review:q('#tr-review').value.slice(0,2000),incidents,laps:p.laps};sessions.push(s);sessions=sessions.slice(-100);persist();selected=s.id;render();}
    function notesView(){return'<div class="tr-notice"><strong>차종별 브레이크 포인트는 실제 게임에서 확인한 기준점을 쌓아 만듭니다.</strong><br>모델의 가상 제동거리로 실제 Monza·Nürburgring의 정답 지점을 생성하지 않습니다. 차량, BoP/패치, 연료, 타이어, 노면 조건과 함께 기록하고 ‘가설’과 ‘실제 심 확인’을 구분하세요.</div><div class="tr-layout"><section class="card tr-form"><h2>코너 기준점 노트</h2><div class="tr-fields">'+formSelect('tr-note-track','코스 키',trackOptions())+formSelect('tr-note-vehicle','차량 계열',vehicleOptions())+formSelect('tr-note-game','게임',games)+field('tr-note-car','실제 차량 / 버전','예: LMU BMW M4 GT3 EVO')+field('tr-note-trackname','실제 트랙·레이아웃 이름','예: Monza GP',true)+'<div class="tr-field wide"><label for="tr-note-corner">코너 또는 구간</label><input id="tr-note-corner" list="tr-corners" maxlength="160" placeholder="예: T1 진입"><datalist id="tr-corners"></datalist></div>'+field('tr-note-reference','브레이킹 기준물·해제·턴인','예: 내가 확인한 보드/노면 표시와 해제 지점',true)+field('tr-note-gear','기어 · 직접 확인한 값','예: 2단 / 확인 전')+formSelect('tr-note-status','확인 상태',[{value:'hypothesis',label:'가설 · 미확인'},{value:'tested',label:'실제 심에서 확인 · 자기기록'}])+field('tr-note-conditions','적용 조건','패치 / BoP / 연료 / 타이어 / 노면 / 셋업',true)+area('tr-note-warning','주의점과 실패 신호','예: 같은 기준점이라도 연료가 많을 때 탈출이 넓어졌음')+'</div><div id="tr-error" class="tr-error" role="alert"></div><div class="tr-actions"><button class="btn primary" id="tr-save-note">코너 노트 저장</button></div></section><section class="card tr-list"><h2>내 차량별 서킷 가이드</h2><p>실제 게임에서 검증한 사실과 아직 시험할 가설을 함께 보관합니다.</p>'+noteCards()+'</section></div><details class="tr-notice" style="margin-top:20px"><summary>향후 서킷 가이드 확장용 데이터 구조</summary><p>트랙 지오메트리와 코너 노트는 분리되어 있습니다. 추후 거리 기반 텔레메트리, 차량·패치별 기준 주행, 코너별 비교 화면을 붙일 수 있습니다. 아래는 현재 내보내는 노트의 구조이며 자동 텔레메트리 수집은 아직 없습니다.</p><pre class="tr-schema">'+esc(JSON.stringify({schemaVersion:1,trackId:'monza',vehicle:'gt3',game:'LMU',car:'직접 입력',corner:'T1',reference:'직접 확인한 기준물',gear:'직접 확인',conditions:'패치·BoP·연료·타이어·노면',status:'hypothesis | tested',warning:'관찰 메모'},null,2))+'</pre></details>';}
    function updateCornerChoices(){const id=q('#tr-note-track').value,track=root.GripTracks?.get(id);q('#tr-corners').innerHTML=(track?.corners||[]).map(c=>'<option value="'+esc(c.name)+'"></option>').join('');q('#tr-note-trackname').value=track?.name||'';}
    function noteCards(){if(!notes.length)return'<div class="tr-empty">아직 코너 노트가 없습니다.<br>한 차·한 트랙·한 코너부터 시작하세요.</div>';return notes.slice().reverse().map(n=>'<article class="tr-item"><span class="tag">'+(n.status==='tested'?'실제 심 확인 · 자기기록':'가설 · 미확인')+'</span><h3>'+esc(n.game)+' / '+esc(n.car)+'<br>'+esc(n.trackName)+' · '+esc(n.corner)+'</h3><p><strong>기준점</strong> '+esc(n.reference)+'</p><p><strong>기어</strong> '+esc(n.gear||'—')+'</p><p><strong>조건</strong> '+esc(n.conditions)+'</p><p>'+esc(n.warning)+'</p>'+(n.trackId!=='custom'?'<button class="btn subtle" data-tr="launch" data-track="'+esc(n.trackId)+'" data-vehicle="'+esc(n.vehicle)+'">관련 평면 코스 열기 ↗</button>':'')+'</article>').join('');}
    function saveNote(){const n={id:Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,6),at:new Date().toISOString(),trackId:q('#tr-note-track').value,vehicle:q('#tr-note-vehicle').value,game:q('#tr-note-game').value,trackName:q('#tr-note-trackname').value.trim(),car:q('#tr-note-car').value.trim(),corner:q('#tr-note-corner').value.trim(),reference:q('#tr-note-reference').value.trim(),gear:q('#tr-note-gear').value.trim(),conditions:q('#tr-note-conditions').value.trim(),warning:q('#tr-note-warning').value.slice(0,2000),status:q('#tr-note-status').value};if(!n.trackName||!n.car||!n.corner||!n.reference||!n.conditions||!validNote(n)){q('#tr-error').textContent='실제 차량·트랙·코너·기준점·조건을 모두 적어 주세요.';return;}notes.push(n);notes=notes.slice(-200);persist();render();}
    element.addEventListener('click',e=>{const b=e.target.closest('[data-tr]');if(!b||!element.contains(b))return;const action=b.dataset.tr;if(action==='stints'||action==='notes'){mode=action;selected=null;render();}else if(action==='detail'){selected=b.dataset.id;render();element.querySelector('.tr-detail')?.scrollIntoView({behavior:'smooth',block:'start'});}else if(action==='close'){selected=null;render();}else if(action==='launch'){onLaunch(b.dataset.track,b.dataset.vehicle);}else if(action==='export'){const url=URL.createObjectURL(new Blob([JSON.stringify({schemaVersion:1,exportedAt:new Date().toISOString(),sessions,cornerNotes:notes},null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='INTS-real-sim-practice.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}});
    render();return{getData:()=>({sessions:JSON.parse(JSON.stringify(sessions)),notes:JSON.parse(JSON.stringify(notes))})};
  }
  const api={mount,parseLaps,stats,lapTime,validSession,validNote};root.GripTransfer=api;if(typeof module!=='undefined'&&module.exports)module.exports=api;
})(typeof globalThis!=='undefined'?globalThis:this);
